set-header.value:
@{
              // Rate limit: lo deja la política en la variable "retry-after".
              if (context.Variables.ContainsKey("retry-after")) {
                  return context.Variables["retry-after"].ToString();
              }
              // Cuota: el mensaje dice "Quota will be replenished in hh:mm:ss".
              var match = System.Text.RegularExpressions.Regex.Match(context.LastError.Message ?? "", @"replenished in ([0-9\.:]+[0-9])");
              TimeSpan wait;
              return match.Success && TimeSpan.TryParse(match.Groups[1].Value, out wait)
                  ? ((int)Math.Ceiling(wait.TotalSeconds)).ToString()
                  : "3600";
          }

return-response.set-body:
@{
            var isQuota = context.LastError.Reason == "QuotaExceeded";
            return new JObject(
                new JProperty("type", "https://tools.ietf.org/html/rfc6585#section-4"),
                new JProperty("title", "Too Many Requests"),
                new JProperty("status", 429),
                new JProperty("detail", isQuota
                    ? "Se agotó la cuota diaria de llamadas para este cliente."
                    : "Demasiadas solicitudes. Espera antes de reintentar (ver header Retry-After)."),
                new JProperty("instance", context.Request.OriginalUrl.Path),
                new JProperty("traceId", context.RequestId.ToString())
            ).ToString();
        }

@{
            var tooLarge = (context.LastError.Message ?? "").Contains("exceeds");
            return new JObject(
                new JProperty("type", tooLarge
                    ? "https://tools.ietf.org/html/rfc9110#section-15.5.14"
                    : "https://tools.ietf.org/html/rfc9110#section-15.5.1"),
                new JProperty("title", tooLarge ? "Payload Too Large" : "Bad Request"),
                new JProperty("status", tooLarge ? 413 : 400),
                new JProperty("detail", context.LastError.Message),
                new JProperty("instance", context.Request.OriginalUrl.Path),
                new JProperty("traceId", context.RequestId.ToString()),
                new JProperty("rechazadoPor", "API Management (" + context.LastError.Source + ")")
            ).ToString();
        }

@{
            return new JObject(
                new JProperty("type", "https://tools.ietf.org/html/rfc9110#section-15.5.2"),
                new JProperty("title", "Unauthorized"),
                new JProperty("status", 401),
                new JProperty("detail", context.LastError.Message),
                new JProperty("instance", context.Request.OriginalUrl.Path),
                new JProperty("traceId", context.RequestId.ToString())
            ).ToString();
        }
